function ipp(; tol = 0, np = AbstractAlgebra, k = np.QQ, internal_ordering = :degrevlex)
    (R, (x1, x2, x3, x4, x5, x6, x7, x8)) = np.polynomial_ring(np.QQ, ["x1", "x2", "x3", "x4", "x5", "x6", "x7", "x8"], internal_ordering = internal_ordering)
    sys = [(x1 ^ 2 + x2 ^ 2) - 1, (x3 ^ 2 + x4 ^ 2) - 1, (x5 ^ 2 + x6 ^ 2) - 1, (x7 ^ 2 + x8 ^ 2) - 1, (((-(rationalize(BigInt, 0.24915068, tol = tol)) * x1 * x3 + rationalize(BigInt, 1.6091354, tol = tol) * x1 * x4 + rationalize(BigInt, 0.27942343, tol = tol) * x2 * x3 + rationalize(BigInt, 1.4348016, tol = tol) * x2 * x4) + (((rationalize(BigInt, 0.40026384, tol = tol) * x5 * x8 - rationalize(BigInt, 0.80052768, tol = tol) * x6 * x7) + rationalize(BigInt, 0.074052388, tol = tol) * x1) - rationalize(BigInt, 0.083050031, tol = tol) * x2)) - ((((rationalize(BigInt, 0.38615961, tol = tol) * x3 - rationalize(BigInt, 0.75526603, tol = tol) * x4) + rationalize(BigInt, 0.50420168, tol = tol) * x5) - rationalize(BigInt, 1.0916287, tol = tol) * x6) + rationalize(BigInt, 0.40026384, tol = tol) * x8)) + rationalize(BigInt, 0.04920729, tol = tol), (((((((rationalize(BigInt, 0.12501635, tol = tol) * x1 * x3 - rationalize(BigInt, 0.68660736, tol = tol) * x1 * x4) - rationalize(BigInt, 0.11922812, tol = tol) * x2 * x3) - rationalize(BigInt, 0.71994047, tol = tol) * x2 * x4) - (((rationalize(BigInt, 0.43241927, tol = tol) * x5 * x7 - rationalize(BigInt, 0.86483855, tol = tol) * x6 * x8) - rationalize(BigInt, 0.03715727, tol = tol) * x1) + rationalize(BigInt, 0.035436896, tol = tol) * x2)) + rationalize(BigInt, 0.085383482, tol = tol) * x3) - rationalize(BigInt, 0.039251967, tol = tol) * x5) - rationalize(BigInt, 0.43241927, tol = tol) * x7) + rationalize(BigInt, 0.01387301, tol = tol), (((((((-(rationalize(BigInt, 0.63555007, tol = tol)) * x1 * x3 - rationalize(BigInt, 0.11571992, tol = tol) * x1 * x4) - rationalize(BigInt, 0.66640448, tol = tol) * x2 * x3) + (rationalize(BigInt, 0.11036211, tol = tol) * x2 * x4 + rationalize(BigInt, 0.29070203, tol = tol) * x5 * x7 + rationalize(BigInt, 1.2587767, tol = tol) * x5 * x8)) - (rationalize(BigInt, 0.62938836, tol = tol) * x6 * x7 + rationalize(BigInt, 0.58140406, tol = tol) * x6 * x8 + rationalize(BigInt, 0.19594662, tol = tol) * x1)) - ((rationalize(BigInt, 1.2280342, tol = tol) * x2 - rationalize(BigInt, 0.079034221, tol = tol) * x4) + rationalize(BigInt, 0.026387877, tol = tol) * x5)) - rationalize(BigInt, 0.05713143, tol = tol) * x6) - rationalize(BigInt, 1.1628081, tol = tol) * x7) + rationalize(BigInt, 1.2587767, tol = tol) * x8 + rationalize(BigInt, 2.162575, tol = tol), (((rationalize(BigInt, 1.4894773, tol = tol) * x1 * x3 + rationalize(BigInt, 0.23062341, tol = tol) * x1 * x4 + rationalize(BigInt, 1.3281073, tol = tol) * x2 * x3) - ((rationalize(BigInt, 0.25864503, tol = tol) * x2 * x4 + rationalize(BigInt, 1.165172, tol = tol) * x5 * x7) - rationalize(BigInt, 0.26908494, tol = tol) * x5 * x8)) + ((rationalize(BigInt, 0.53816987, tol = tol) * x6 * x7 + rationalize(BigInt, 0.58258598, tol = tol) * x6 * x8) - rationalize(BigInt, 0.20816985, tol = tol) * x1) + ((rationalize(BigInt, 2.686832, tol = tol) * x2 - rationalize(BigInt, 0.69910317, tol = tol) * x3) + rationalize(BigInt, 0.35744413, tol = tol) * x4) + rationalize(BigInt, 1.2499117, tol = tol) * x5 + rationalize(BigInt, 1.467736, tol = tol) * x6 + rationalize(BigInt, 1.165172, tol = tol) * x7 + rationalize(BigInt, 1.10763397, tol = tol) * x8) - rationalize(BigInt, 0.69686809, tol = tol)]
    sys = map((f->begin
                    AbstractAlgebra.map_coefficients((c->begin
                                k(BigInt(numerator(c))) // k(BigInt(denominator(c)))
                            end), f)
                end), sys)
    sys
end
